node << 'EOF'
const fs = require('fs');

// Read environment variables from .env.test
const envContent = fs.readFileSync('.env.test', 'utf8');
const envVars = {};

envContent.split('\n').forEach(line => {
    line = line.trim();
    if (line && !line.startsWith('#')) {
        const parts = line.split('=');
        if (parts.length === 2) {
            envVars[parts[0]] = parts[1];
        }
    }
});

// Convert to JSON format with key/value pairs
const payload = {
    environment_variables: Object.keys(envVars).map(key => ({
        key: key,
        value: envVars[key]
    }))
};

console.log(JSON.stringify(payload, null, 2));
EOF

